import logging
import queue
import threading

logger = logging.getLogger(__name__)

_SHUTDOWN = object()


class QueueWorker:
    """Runs a callback against each item pushed onto an internal queue."""

    def __init__(self, handler, name="queue-worker", max_pending=0):
        self.handler = handler
        self.queue = queue.Queue(maxsize=max_pending)
        self.thread = threading.Thread(target=self._drain, name=name, daemon=True)
        self._started = False

    def start(self):
        if self._started:
            raise RuntimeError("worker already started")
        self._started = True
        self.thread.start()

    def submit(self, item, block=True, timeout=None):
        if not self._started:
            raise RuntimeError("worker not started")
        self.queue.put(item, block=block, timeout=timeout)

    def _drain(self):
        while True:
            item = self.queue.get()
            try:
                if item is _SHUTDOWN:
                    return
                self.handler(item)
            except Exception:
                logger.exception("handler failed for %r", item)
            finally:
                self.queue.task_done()

    def join(self):
        """Blocks until everything submitted so far has been handled."""
        self.queue.join()

    def stop(self, timeout=None):
        if not self._started:
            return
        self.queue.put(_SHUTDOWN)
        self.thread.join(timeout)
        if self.thread.is_alive():
            logger.warning("worker thread did not exit within %s seconds", timeout)
        self._started = False

    def __enter__(self):
        self.start()
        return self

    def __exit__(self, exc_type, exc, tb):
        self.stop()
        return False
