```python
import logging
import queue
import threading

logger = logging.getLogger(__name__)

_SHUTDOWN = object()


class QueueWorker:
    """Runs a callback against each item pushed onto an internal queue."""

    def __init__(self, handler, name="queue-worker", max_pending=0):
        self.handler = handler
        self.queue = queue.Queue(maxsize=max_pending)
        self.thread = threading.Thread(target=self._drain, name=name, daemon=True)
        self._lock = threading.Lock()
        self._state = "new"

    def start(self):
        with self._lock:
            if self._state != "new":
                raise RuntimeError(f"worker is {self._state}, cannot start")
            self._state = "running"
        self.thread.start()

    def submit(self, item, block=True, timeout=None):
        with self._lock:
            if self._state != "running":
                raise RuntimeError(f"worker is {self._state}, not accepting items")
        self.queue.put(item, block=block, timeout=timeout)

    def _drain(self):
        while True:
            item = self.queue.get()
            try:
                if item is _SHUTDOWN:
                    logger.debug("sentinel received, draining stopped")
                    return
                self.handler(item)
            except Exception:
                logger.exception("handler failed for %r", item)
            finally:
                self.queue.task_done()

    def join(self):
        """Blocks until everything submitted so far has been handled."""
        self.queue.join()

    def stop(self, timeout=None):
        """Queues the sentinel behind pending items and waits for the thread."""
        with self._lock:
            if self._state != "running":
                return
            self._state = "stopping"
        self.queue.put(_SHUTDOWN)
        self.thread.join(timeout)
        if self.thread.is_alive():
            logger.warning("worker thread still alive after %ss", timeout)
        else:
            self._state = "stopped"

    def __enter__(self):
        self.start()
        return self

    def __exit__(self, exc_type, exc, tb):
        self.stop()
        return False
